UPDATE presale_report_version
SET generation_status = 'RUNNING',
    updated_at = NOW()
WHERE id = #{versionId}
  AND generation_status = 'QUEUED'
  AND (
      SELECT running_count
      FROM (
          SELECT COUNT(1) AS running_count
          FROM presale_report_version
          WHERE generation_status = 'RUNNING'
      ) active_generations
  ) < #{maxRunning}
